 static object PaletteValue(Style style,DependencyProperty property,object value){if(!(value is System.Windows.Media.Brush))return value;if(property==Control.ForegroundProperty)return (style.TargetType==typeof(DataGridColumnHeader)?Theme.Muted:Theme.Ink).CloneCurrentValue();if(property==Control.BackgroundProperty)return (style.TargetType==typeof(DataGridColumnHeader)?Theme.Surface:Theme.Raised).CloneCurrentValue();if(property==Control.BorderBrushProperty)return Theme.Line.CloneCurrentValue();return value;}
 static Style RecolorStyle(Style original){var result=new Style(original.TargetType);foreach(var setter in original.Setters.OfType<Setter>())result.Setters.Add(new Setter(setter.Property,PaletteValue(original,setter.Property,setter.Value)));foreach(var trigger in original.Triggers.OfType<Trigger>()){var copy=new Trigger{Property=trigger.Property,Value=trigger.Value};foreach(var setter in trigger.Setters.OfType<Setter>())copy.Setters.Add(new Setter(setter.Property,PaletteValue(original,setter.Property,setter.Value)));result.Triggers.Add(copy);}return result;}
 static void RefreshControls(DependencyObject element){var grid=element as DataGrid;if(grid!=null){grid.Background=Theme.Surface;grid.Foreground=Theme.Ink;grid.BorderBrush=Theme.Line;if(grid.CellStyle!=null)grid.CellStyle=RecolorStyle(grid.CellStyle);foreach(var column in grid.Columns)if(column.HeaderStyle!=null)column.HeaderStyle=RecolorStyle(column.HeaderStyle);}var box=element as TextBox;if(box!=null){box.Background=Theme.Surface;box.Foreground=Theme.Ink;box.BorderBrush=Theme.Line;}var button=element as Button;if(button!=null){button.Background=(object.Equals(button.Tag,"flat")||object.Equals(button.Tag,"breadcrumb"))?System.Windows.Media.Brushes.Transparent:Theme.Raised;button.Foreground=Theme.Ink;button.BorderBrush=Theme.Line;}var expander=element as Expander;if(expander!=null)expander.Foreground=Theme.Ink;var check=element as CheckBox;if(check!=null)check.Foreground=Theme.Muted;var text=element as TextBlock;if(text!=null)text.Foreground=Theme.Muted;foreach(var child in LogicalTreeHelper.GetChildren(element).OfType<DependencyObject>().ToArray())RefreshControls(child);}

 public void SetServer(Server value){if(value==null)return;if(server!=null&&FileTools.Key(server)==FileTools.Key(value))return;server=value.Copy();UpdatePaneLayout();back.Clear();forward.Clear();ClearCache();current="";crumbs.Children.Clear();CancelPathEdit();rows.Clear();all=new List<FileEntry>();Navigate("",false,false);}
 void NavigateHistory(bool next){var src=next?forward:back;var dst=next?back:forward;if(src.Count==0)return;dst.Push(current);Navigate(src.Pop(),false,false);}
 void PostNavigation(Action update){if(!Dispatcher.HasShutdownStarted)Dispatcher.BeginInvoke(update);}
 public async void Navigate(string requested,bool record,bool force){if(disposed||Dispatcher.HasShutdownStarted)return;if(!Dispatcher.CheckAccess()){PostNavigation(()=>Navigate(requested,record,force));return;}loading=true;var device=server.Copy();int version;lock(cacheGate){version=++generation;}listing.Cancel();listing.Dispose();listing=new CancellationTokenSource();var token=listing.Token;string previous=current;rows.Clear();all=new List<FileEntry>();treeChildren.Clear();treeExpanded.Clear();status.Text="正在读取目录…";target.Text=device.IsLocal?"本机文件":device.Name+" · SFTP";try{var result=await Task.Run(async()=>{if(!force&&!string.IsNullOrWhiteSpace(requested)&&(device.IsLocal?Path.IsPathRooted(requested):requested.StartsWith("/"))){string cachedPath=device.IsLocal?Path.GetFullPath(requested):requested;string cachedKey=FileTools.Key(device)+"\n"+cachedPath;Cache hit;lock(cacheGate){if(cache.TryGetValue(cachedKey,out hit)&&(DateTime.UtcNow-hit.Stamp).TotalSeconds<8)return Tuple.Create(cachedPath,new List<FileEntry>(hit.Entries));}}using(var conn=new FileConnection(device)){await conn.Connect(token).ConfigureAwait(false);string dir=string.IsNullOrWhiteSpace(requested)?conn.Home:requested.Trim();if(device.IsLocal)dir=Path.GetFullPath(dir);else if(dir=="~")dir=conn.Home;else if(dir.StartsWith("~/"))dir=conn.Home.TrimEnd('/')+dir.Substring(1);else if(!dir.StartsWith("/"))dir=FileTools.Join(false,string.IsNullOrEmpty(previous)?conn.Home:previous,dir);string key=FileTools.Key(device)+"\n"+dir;Cache found;lock(cacheGate){if(!force&&cache.TryGetValue(key,out found)&&(DateTime.UtcNow-found.Stamp).TotalSeconds<8)return Tuple.Create(dir,new List<FileEntry>(found.Entries));}
 var entries=conn.List(dir,token);lock(cacheGate){if(token.IsCancellationRequested||version!=generation)throw new OperationCanceledException(token);cache[key]=new Cache{Stamp=DateTime.UtcNow,Entries=new List<FileEntry>(entries)};if(cache.Count>30)cache.Remove(cache.Keys.First());}return Tuple.Create(dir,entries);}},token).ConfigureAwait(false);if(disposed||Dispatcher.HasShutdownStarted)return;
 await Dispatcher.InvokeAsync(new Func<Task>(async()=>{if(disposed||version!=generation||token.IsCancellationRequested)return;if(record&&previous.Length>0&&previous!=result.Item1){back.Push(previous);forward.Clear();}current=result.Item1;target.Text=device.IsLocal?"本机文件":device.Name+" · SFTP";path.ToolTip=target.Text;files.ToolTip="拖入上传目标："+target.Text;path.Text=current;CancelPathEdit();all=new List<FileEntry>(result.Item2);BuildCrumbs();await ApplyRows(version,token);if(disposed||version!=generation||token.IsCancellationRequested)return;loading=false;backButton.IsEnabled=back.Count>0;forwardButton.IsEnabled=forward.Count>0;})).Task.Unwrap().ConfigureAwait(false);
 }catch(OperationCanceledException){}catch(Exception ex){if(Dispatcher.HasShutdownStarted)return;string message=ex.Message;PostNavigation(()=>{if(version==generation&&!disposed){loading=false;status.Text="目录读取失败："+message;path.Text=previous;}});}}

 async Task ApplyRows(int version,CancellationToken token){int filterStamp=++filterVersion;rows.Clear();var selected=Filtered();for(int i=0;i<selected.Count;i+=180){if(disposed||version!=generation||token.IsCancellationRequested||filterStamp!=filterVersion)return;foreach(var x in selected.Skip(i).Take(180))rows.Add(x);await Dispatcher.InvokeAsync(()=>{},System.Windows.Threading.DispatcherPriority.Background);}if(version==generation)status.Text=selected.Count+" 项";}
 List<FileEntry> Filtered(){string query=filter==null?"":filter.Text;return all.Where(x=>(showHidden||!x.Name.StartsWith("."))&&(string.IsNullOrEmpty(query)||x.Name.IndexOf(query,StringComparison.CurrentCultureIgnoreCase)>=0)).ToList();}
 void ApplyFilter(){filterVersion++;if(files==null)return;RenderTree();if(status!=null)status.Text=rows.Count+" 项 · 当前目录 "+all.Count+" 项";}
 public void BeginPathEdit(){editingPath=true;path.Text=current;path.Visibility=Visibility.Visible;crumbs.Visibility=Visibility.Collapsed;editPathButton.Content="↵";editPathButton.ToolTip="前往输入的路径（Enter）";path.Focus();path.SelectAll();}
