 public void SubmitPathEdit(){string requested=path.Text;CancelPathEdit();Navigate(requested,true,false);}
 Button PathSegment(string title,string destination,double maximum=180){var b=Button(title,()=>{if(destination!=null)Navigate(destination,true,false);});b.Tag="breadcrumb";b.CommandParameter=destination;b.ToolTip=destination;b.FontSize=15;b.MaxWidth=maximum;b.Background=System.Windows.Media.Brushes.Transparent;b.BorderThickness=new Thickness(0);b.Padding=new Thickness(8,0,8,0);b.Margin=new Thickness(0);var label=Theme.Text(title,15,Theme.Ink);label.MaxWidth=Math.Max(20,maximum-16);label.TextTrimming=TextTrimming.CharacterEllipsis;b.Content=label;var template=new ControlTemplate(typeof(Button));var border=new FrameworkElementFactory(typeof(Border));border.Name="chrome";border.SetBinding(Border.PaddingProperty,new Binding("Padding"){RelativeSource=RelativeSource.TemplatedParent});border.SetValue(Border.CornerRadiusProperty,new CornerRadius(4));border.SetBinding(Border.BackgroundProperty,new Binding("Background"){RelativeSource=RelativeSource.TemplatedParent});var content=new FrameworkElementFactory(typeof(ContentPresenter));content.SetValue(FrameworkElement.HorizontalAlignmentProperty,HorizontalAlignment.Center);content.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);content.SetBinding(ContentPresenter.ContentProperty,new Binding("Content"){RelativeSource=RelativeSource.TemplatedParent});border.AppendChild(content);template.VisualTree=border;var hover=new Trigger{Property=UIElement.IsMouseOverProperty,Value=true};hover.Setters.Add(new Setter(Border.BackgroundProperty,Theme.Raised.CloneCurrentValue(),"chrome"));template.Triggers.Add(hover);b.Template=template;return b;}
 void BuildCrumbs(){if(crumbs==null||server==null||current.Length==0)return;crumbs.Children.Clear();var parts=FileTools.PathParts(server.IsLocal,current);double available=Math.Max(90,(addressChrome.ActualWidth>0?addressChrome.ActualWidth:600)-14);var widths=parts.Select(x=>{var text=Theme.Text(x.Item1,15,Theme.Ink);text.Measure(new Size(double.PositiveInfinity,32));return Math.Min(180,text.DesiredSize.Width+16);}).ToArray();double allWidth=widths.Sum()+Math.Max(0,parts.Count-1)*28;var visible=new List<int>();int omittedEnd=-1;if(allWidth<=available){for(int i=0;i<parts.Count;i++)visible.Add(i);}else{visible.Add(0);double used=widths[0]+44;int first=parts.Count-1;for(int i=parts.Count-1;i>=1;i--){if(i!=parts.Count-1&&used+widths[i]+28>available)break;used+=widths[i]+28;first=i;}omittedEnd=first-1;for(int i=first;i<parts.Count;i++)visible.Add(i);}
 Action<int> separator=(parentIndex)=>{var arrow=PathSegment("›",null,28);arrow.Tag="breadcrumb";arrow.ToolTip="子文件夹";string parent=parts[Math.Max(0,parentIndex)].Item2;arrow.Click+=(o,e)=>OpenChildrenMenu(arrow,parent);crumbs.Children.Add(arrow);};for(int index=0;index<visible.Count;index++){int item=visible[index];if(index>0)separator(visible[index-1]);if(index==1&&omittedEnd>=1){var overflow=PathSegment("…",null,32);overflow.CommandParameter=null;overflow.ToolTip="展开中间目录";var menu=new ContextMenu{Background=Theme.Surface,Foreground=Theme.Ink,BorderBrush=Theme.Line,BorderThickness=new Thickness(1),Padding=new Thickness(4)};for(int i=1;i<=omittedEnd;i++){string dest=parts[i].Item2;var entry=new MenuItem{Header=parts[i].Item1,ToolTip=dest,CommandParameter=dest,Style=MenuStyle()};entry.Click+=(o,e)=>Navigate(dest,true,false);menu.Items.Add(entry);}overflow.ContextMenu=menu;overflow.Click+=(o,e)=>{menu.PlacementTarget=overflow;menu.IsOpen=true;};crumbs.Children.Add(overflow);separator(omittedEnd);}double max=parts.Count==1?Math.Min(180,available):item==parts.Count-1?Math.Max(40,Math.Min(180,available-widths[0]-58)):180;var button=PathSegment(parts[item].Item1,parts[item].Item2,max);crumbs.Children.Add(button);if(item==parts.Count-1)separator(item);}}

 sealed class RemoteDrag { public Server Device; public string[] Paths; }
 static T Ancestor<T>(DependencyObject child) where T:DependencyObject {while(child!=null){var found=child as T;if(found!=null)return found;child=System.Windows.Media.VisualTreeHelper.GetParent(child);}return null;}
 void BuildDualPane(){var right=new Grid();foreach(var definition in RowDefinitions.ToArray())right.RowDefinitions.Add(new RowDefinition{Height=definition.Height});var content=Children.Cast<UIElement>().ToArray();Children.Clear();RowDefinitions.Clear();foreach(var child in content)right.Children.Add(child);dualGrid=new Grid();dualGrid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});dualGrid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(16)});dualGrid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1.25,GridUnitType.Star)});localPane=new FileWorkspace(new Server{IsLocal=true,Name="本机"},false);dualGrid.Children.Add(localPane);Grid.SetColumn(right,2);dualGrid.Children.Add(right);fileDivider=PaneDivider.Ratio(dualGrid,0,2,"files.columns",1/2.25);UpdatePaneLayout();Children.Add(dualGrid);}
 void UpdatePaneLayout(){if(localPane==null||fileDivider==null||server==null)return;bool dual=!server.IsLocal;localPane.Visibility=dual?Visibility.Visible:Visibility.Collapsed;fileDivider.Visibility=dual?Visibility.Visible:Visibility.Collapsed;dualGrid.ColumnDefinitions[1].Width=new GridLength(dual?16:0);if(dual)fileDivider.Restore(false);else{dualGrid.ColumnDefinitions[0].MinWidth=0;dualGrid.ColumnDefinitions[0].Width=new GridLength(0);dualGrid.ColumnDefinitions[2].Width=new GridLength(1,GridUnitType.Star);}}
 void RenderTree(){rows.Clear();foreach(var entry in Filtered()){rows.Add(entry);AppendChildren(entry);}}
 void AppendChildren(FileEntry parent){List<FileEntry> children;if(!treeExpanded.Contains(parent.FullPath)||!treeChildren.TryGetValue(parent.FullPath,out children))return;foreach(var child in children.Where(x=>showHidden||!x.Name.StartsWith("."))){rows.Add(child);AppendChildren(child);}}
 public async void ToggleDirectory(FileEntry entry){if(entry==null||!entry.IsDirectory||entry.IsLink)return;string key=entry.FullPath;int version=generation;if(treeExpanded.Remove(key)){entry.Expanded=false;entry.Expanding=false;entry.Notify();RenderTree();return;}treeExpanded.Add(key);entry.Expanded=true;entry.Expanding=true;entry.Notify();try{List<FileEntry> children;if(!treeChildren.TryGetValue(key,out children)){var device=server.Copy();var token=listing.Token;children=await Task.Run(async()=>{using(var connection=new FileConnection(device)){await connection.Connect(token).ConfigureAwait(false);return connection.List(key,token);}},token);if(disposed||version!=generation||!treeExpanded.Contains(key))return;foreach(var child in children)child.Depth=entry.Depth+1;treeChildren[key]=children;}if(version==generation&&treeExpanded.Contains(key)){entry.Expanding=false;entry.Notify();RenderTree();}}catch(OperationCanceledException){}catch(Exception ex){if(version==generation){treeExpanded.Remove(key);entry.Expanded=entry.Expanding=false;entry.Notify();status.Text="无法展开："+ex.Message;}}}
 async void OpenChildrenMenu(Button owner,string directory){int version=generation;var device=server.Copy();var menu=new ContextMenu{Resources=Theme.Resources(),Background=Theme.Surface,Foreground=Theme.Ink,BorderBrush=Theme.Line,BorderThickness=new Thickness(1),Padding=new Thickness(4),PlacementTarget=owner};menu.Items.Add(new MenuItem{Header="正在读取…",IsEnabled=false});menu.IsOpen=true;try{var children=await Task.Run(async()=>{using(var connection=new FileConnection(device)){await connection.Connect(listing.Token).ConfigureAwait(false);return connection.List(directory,listing.Token).Where(x=>x.IsDirectory).ToArray();}});if(disposed||version!=generation){menu.IsOpen=false;return;}menu.Items.Clear();foreach(var child in children){string destination=child.FullPath;var item=new MenuItem{Header=child.Name,ToolTip=destination,Style=MenuStyle()};item.Click+=(o,e)=>Navigate(destination,true,false);menu.Items.Add(item);}if(children.Length==0)menu.Items.Add(new MenuItem{Header="没有子文件夹",IsEnabled=false});}catch(Exception ex){menu.Items.Clear();menu.Items.Add(new MenuItem{Header="读取失败："+ex.Message,IsEnabled=false});}}
 string[] SelectionPaths(){var selected=files.SelectedItems.Cast<FileEntry>().ToArray();return selected.Where(x=>!selected.Any(parent=>parent!=x&&parent.IsDirectory&&x.FullPath.StartsWith(parent.FullPath.TrimEnd('/','\\')+(server.IsLocal?"\\":"/"),server.IsLocal?StringComparison.OrdinalIgnoreCase:StringComparison.Ordinal))).Select(x=>x.FullPath).ToArray();}
 async void BeginFileDrag(object sender,MouseEventArgs e){if(e.LeftButton!=MouseButtonState.Pressed||stagingDrag||loading)return;var point=e.GetPosition(files);if(Math.Abs(point.X-dragStart.X)<SystemParameters.MinimumHorizontalDragDistance&&Math.Abs(point.Y-dragStart.Y)<SystemParameters.MinimumVerticalDragDistance)return;var selected=SelectionPaths();if(selected.Length==0)return;dragStart=point;var data=new DataObject();if(server.IsLocal)data.SetData(DataFormats.FileDrop,selected);else{data.SetData("AQServer.RemoteFiles",new RemoteDrag{Device=server.Copy(),Paths=selected});string key=FileTools.Key(server)+"\n"+string.Join("\n",selected);if(stagedKey==key&&stagedPaths!=null)data.SetData(DataFormats.FileDrop,stagedPaths);else{stagingDrag=true;status.Text="正在准备拖出文件…";string destination=Path.Combine(Path.GetTempPath(),"AQServer-Drag",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(destination);var before=new HashSet<FileTransfer>(transfers.Items);await Plan(server.Copy(),false,selected,destination);var jobs=transfers.Items.Where(x=>!before.Contains(x)).ToArray();while(!disposed&&jobs.Any(x=>x.IsRunning))await Task.Delay(80);stagingDrag=false;if(disposed)return;if(jobs.Any(x=>x.State!="已完成")){status.Text="拖出准备未完成，请在传输队列重试。";return;}stagedPaths=Directory.GetFileSystemEntries(destination);stagedKey=key;status.Text="已准备 "+stagedPaths.Length+" 项，再次拖动可放入资源管理器。";if(e.LeftButton!=MouseButtonState.Pressed)return;data.SetData(DataFormats.FileDrop,stagedPaths);}}DragDrop.DoDragDrop(files,data,DragDropEffects.Copy);}
 void PickUpload(){var dialog=new OpenFileDialog{Multiselect=true,Title="选择上传文件（文件夹可直接拖入文件列表）"};if(dialog.ShowDialog(Window.GetWindow(this))==true)PrepareUpload(dialog.FileNames);}
 async void PrepareUpload(string[] paths){if(loading||current.Length==0){status.Text="请等待目标目录加载完成后再上传。";return;}var device=server.Copy();string destination=current;await Plan(device,true,paths,destination);}
 async void Download(){var selected=files.SelectedItems.Cast<FileEntry>().ToArray();if(selected.Length==0){status.Text="请先选择要下载的文件或文件夹。";return;}using(var dialog=new Forms.FolderBrowserDialog{Description="选择本机下载位置",ShowNewFolderButton=true}){if(dialog.ShowDialog()!=Forms.DialogResult.OK)return;await Plan(server.Copy(),false,selected.Select(x=>x.FullPath).ToArray(),dialog.SelectedPath);}}
 async Task Plan(Server device,bool upload,string[] sources,string destination){var token=planning.Token;status.Text="正在准备传输；目标 "+device.Name+" · "+destination;try{await Task.Run(async()=>{using(var remote=new FileConnection(device))using(var local=new FileConnection(new Server{IsLocal=true,Name="本机"})){await remote.Connect(token).ConfigureAwait(false);await local.Connect(token).ConfigureAwait(false);var src=upload?local:remote;var dst=upload?remote:local;foreach(string p in sources){token.ThrowIfCancellationRequested();string name=upload?Path.GetFileName(p.TrimEnd('\\','/')):p.TrimEnd('/').Split('/').Last();if(string.IsNullOrWhiteSpace(name)||name=="."||name=="..")continue;await PlanOne(device,upload,src,dst,p,(dst.Device.IsLocal?FileTools.LocalChild(destination,destination,name):FileTools.Join(false,destination,name)),destination,token).ConfigureAwait(false);}}},token);if(!disposed)status.Text="任务已加入传输队列 · "+device.Name+" · "+destination;}catch(OperationCanceledException){}catch(Exception ex){if(!disposed)status.Text="传输准备失败："+ex.Message;}}
 async Task PlanOne(Server device,bool upload,FileConnection src,FileConnection dst,string source,string dest,string destinationRoot,CancellationToken token){token.ThrowIfCancellationRequested();if(dst.Device.IsLocal)FileTools.EnsureUnderRoot(destinationRoot,dest);bool dir;if(src.Device.IsLocal){var attributes=File.GetAttributes(source);if((attributes&FileAttributes.ReparsePoint)!=0)throw new IOException("为避免循环或跨目录复制，暂不传输符号链接："+source);dir=(attributes&FileAttributes.Directory)!=0;}else{if(src.IsLink(source))throw new IOException("暂不递归传输符号链接："+source);dir=src.IsDirectory(source);}
 if(dir){if(src.Device.IsLocal&&dst.Device.IsLocal)FileTools.RejectRecursiveLocalCopy(source,dest);dst.MakeDirectory(dest);foreach(var item in src.List(source,token)){if(item.IsLink)continue;await PlanOne(device,upload,src,dst,item.FullPath,(dst.Device.IsLocal?FileTools.LocalChild(destinationRoot,dest,item.Name):FileTools.Join(false,dest,item.Name)),destinationRoot,token).ConfigureAwait(false);}return;}
 bool replace=false;if(dst.Exists(dest)){FileCollision answer=await Dispatcher.InvokeAsync(()=>Collision(device,dest,upload));if(answer==FileCollision.Cancel)throw new OperationCanceledException();if(answer==FileCollision.Skip)return;if(answer==FileCollision.Rename){string parent=FileTools.Parent(dst.Device.IsLocal,dest),name=Path.GetFileName(dest),ext=Path.GetExtension(name),stem=Path.GetFileNameWithoutExtension(name);int i=1;do{string renamed=stem+" ("+(i++)+")"+ext;dest=dst.Device.IsLocal?FileTools.LocalChild(destinationRoot,parent,renamed):FileTools.Join(false,parent,renamed);}while(dst.Exists(dest));}else replace=true;}
 var job=new FileTransfer(device,upload,source,dest,replace,src.Length(source),dst.Device.IsLocal?destinationRoot:null);await Dispatcher.InvokeAsync(()=>{if(!disposed)transfers.Add(job);});}
 FileCollision Collision(Server device,string dest,bool upload){var win=new Window{Title="处理同名文件",Width=550,SizeToContent=SizeToContent.Height,WindowStartupLocation=WindowStartupLocation.CenterOwner,Owner=Window.GetWindow(this),Background=Theme.Bg,Foreground=Theme.Ink,Resources=Theme.Resources(),ResizeMode=ResizeMode.NoResize};var panel=new StackPanel{Margin=new Thickness(20)};panel.Children.Add(new TextBlock{Text="目标已存在\n"+(upload?device.Name:"本机")+" · "+dest+"\n选择替换时，完整临时文件验证后才提交。",TextWrapping=TextWrapping.Wrap,Foreground=Theme.Ink,Margin=new Thickness(0,0,0,20)});var buttons=new WrapPanel();FileCollision result=FileCollision.Cancel;foreach(var choice in new[]{Tuple.Create("跳过",FileCollision.Skip),Tuple.Create("自动重命名",FileCollision.Rename),Tuple.Create("替换",FileCollision.Replace),Tuple.Create("取消本批",FileCollision.Cancel)}){var option=choice;buttons.Children.Add(Button(option.Item1,()=>{result=option.Item2;win.Close();}));}panel.Children.Add(buttons);win.Content=panel;win.ShowDialog();return result;}
 async void Preview(){var file=files.SelectedItem as FileEntry;if(file==null||file.IsDirectory)return;if(file.Size>262144){status.Text="文本预览限制 256 KB；请下载后查看。";return;}var device=server.Copy();int version=generation;try{string text=await Task.Run(async()=>{using(var conn=new FileConnection(device)){await conn.Connect(listing.Token).ConfigureAwait(false);using(var stream=conn.OpenRead(file.FullPath)){byte[] bytes=new byte[262145];int total=0,n;while(total<bytes.Length&&(n=await stream.ReadAsync(bytes,total,bytes.Length-total).ConfigureAwait(false))>0)total+=n;if(total>262144||Array.IndexOf(bytes,(byte)0,0,total)>=0)throw new IOException("此文件不是可预览的小型文本。");return System.Text.Encoding.UTF8.GetString(bytes,0,total);}}});if(version!=generation||disposed)return;var win=new Window{Title=file.Name+" · 只读预览（UTF-8）",Width=850,Height=600,Owner=Window.GetWindow(this),WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=Theme.Bg,Resources=Theme.Resources()};win.Content=new TextBox{Text=text,IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.NoWrap,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Background=Theme.Surface,Foreground=Theme.Ink,FontFamily=Theme.Mono,Padding=new Thickness(16)};previews.Add(win);win.Closed+=(o,e)=>previews.Remove(win);win.Show();}catch(Exception ex){status.Text="预览失败："+ex.Message;}}
 public void Dispose(){disposed=true;generation++;listing.Cancel();planning.Cancel();transfers.Dispose();if(localPane!=null)localPane.Dispose();}
